templates.template:
.p-header-content {
	display: flex;
	justify-content: 	<xf:if is="property('svg_textSlogan_location') == 'row-reverse'">
							<xf:if is="property('svg_textLogo_align') == 'flex-start'">
								flex-end
							<xf:elseif is="property('svg_textLogo_align') == 'flex-end'" />
								flex-start
							</xf:if>
						<xf:else />
							@xf-svg_textLogo_align
						</xf:if>;
	flex-flow: @xf-svg_textSlogan_location;
	align-items: {{ (property('svg_textSlogan_location') == 'column' || property('svg_textSlogan_location') == 'column-reverse')  ? property('svg_textLogo_align') : 'center' }};
	align-content: center;
	padding: 5px 0 10px;
	.p-header-logo {
		margin-right: 10px;
		.svg-forum-logo {
			display: block;
			.xf-svg_forumLogo();
			margin: 0;
		}
	}
	.svg-forum-slogan {
		display: block;
		.xf-svg_forumSlogan();
		margin: 0;
	}
}

.p-nav-smallLogo {
	a {
		.xf-svg_smallLogo_style();
		white-space: nowrap;
		text-decoration: none;
	}	
}

<xf:if is="property('svg_header_disable')">
	.p-header-inner {
		display: none;
	}
	.p-nav-smallLogo {
		display: block;
		margin: 0 10px;
	}
</xf:if>
